import sys
from collections import Counter
from png import load, px

BG = (40,42,54)

def solid_color_at(img, w, x, y):
    r,g,b,a = px(img,w,x,y)
    return (r,g,b)

def line_bands(img, w, h):
    # find y bands with ink pixels (non-bg, saturated enough)
    rows = []
    for y in range(200, h):
        cnt = 0
        for x in range(280, w-280):
            r,g,b,a = px(img,w,x,y)
            if (r,g,b) != BG and a==255 and max(abs(r-BG[0]),abs(g-BG[1]),abs(b-BG[2]))>40:
                cnt += 1
        rows.append((y,cnt))
    bands = []
    cur = None
    for y,c in rows:
        if c > 3:
            if cur is None: cur = [y,y]
            else: cur[1] = y
        else:
            if cur is not None and cur[1]-cur[0] > 5:
                bands.append(tuple(cur))
            if cur is None or c <= 3:
                if cur is not None: cur=None
    if cur and cur[1]-cur[0]>5: bands.append(tuple(cur))
    return bands

def line_colors(img, w, y0, y1):
    # dominant solid colors in this band, with min/max x per color
    counter = Counter()
    xs = {}
    for y in range(y0, y1+1):
        for x in range(280, w-280):
            r,g,b,a = px(img,w,x,y)
            if a != 255: continue
            c = (r,g,b)
            if c == BG: continue
            # skip near-bg antialiasing: require distance
            if max(abs(r-BG[0]),abs(g-BG[1]),abs(b-BG[2])) <= 40: continue
            counter[c] += 1
            if c not in xs: xs[c] = [x,x]
            else:
                xs[c][0]=min(xs[c][0],x); xs[c][1]=max(xs[c][1],x)
    return counter.most_common(8), xs

path = sys.argv[1]
img, w, h = load(path)
print(path, "size", w, h)
bands = line_bands(img, w, h)
for i,(y0,y1) in enumerate(bands):
    common, xs = line_colors(img, w, y0, y1)
    print(f"line{i+1} y=[{y0},{y1}]")
    for c,n in common:
        print(f"   {c} n={n} x=[{xs[c][0]},{xs[c][1]}]")
